-- OBSIDIAN / Space + Halloween / v6
-- Executor edition: run this one file. Both user-provided images are embedded.
-- Images use writefile + getcustomasset/getsynasset; no upload or HTTP required.
-- Preferences are saved automatically per account and experience across rejoins.
-- Set this to the uploaded Roblox Image ID for Obsidian-Logo.png.
-- Example format: "rbxassetid://YOUR_IMAGE_ID" (use your actual numeric ID).
-- The attached logo is embedded below, so no upload or separate image is required.
local function loadEmbeddedImage(encoded,path)
 local importAsset=getcustomasset or getsynasset
 if type(importAsset)~='function' or type(writefile)~='function' then
  warn('Obsidian: this executor needs getcustomasset/getsynasset and writefile to display the attached logo.')
  return ''
 end

 local exists=false
 if type(isfile)=='function' then local ok,value=pcall(isfile,path); exists=ok and value end
 if not exists then

  local decoded
  if type(crypt)=='table' and type(crypt.base64)=='table' and type(crypt.base64.decode)=='function' then
   local ok,value=pcall(crypt.base64.decode,encoded)
   if ok then decoded=value end
  end
  if type(decoded)~='string' or (decoded:sub(1,8)~='\137PNG\13\10\26\10' and decoded:sub(1,3)~='\255\216\255') then
   local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
   local values={}
   for i=1,64 do values[alphabet:sub(i,i)]=i-1 end
   local chunks={}
   for i=1,#encoded,4 do
    local a,b,c,d=encoded:sub(i,i),encoded:sub(i+1,i+1),encoded:sub(i+2,i+2),encoded:sub(i+3,i+3)
    local n=values[a]*262144+values[b]*4096+(values[c] or 0)*64+(values[d] or 0)
    chunks[#chunks+1]=string.char(math.floor(n/65536)%256)
    if c~='=' then chunks[#chunks+1]=string.char(math.floor(n/256)%256) end
    if d~='=' then chunks[#chunks+1]=string.char(n%256) end
    if i%16384==1 then task.wait() end
   end
   decoded=table.concat(chunks)
  end
  assert((decoded:sub(1,8)=='\137PNG\13\10\26\10' or decoded:sub(1,3)=='\255\216\255'),'Invalid embedded logo')
  local ok,err=pcall(writefile,path,decoded)
  if not ok then warn('Obsidian: could not save logo: '..tostring(err)); return '' end
 end
 local ok,asset=pcall(importAsset,path)
 if not ok then warn('Obsidian: could not load logo: '..tostring(asset)); return '' end
 return asset
end


