-- Disk preferences are isolated by Roblox account and experience.
local persistence=(function()
 local http=game:GetService('HttpService')
 local folder='FyrelithSettings'
 local filename=folder..'/'..tostring(player.UserId)..'-'..tostring(game.GameId)..'.json'
 local p={Data={},Available=type(readfile)=='function' and type(writefile)=='function',Path=filename}
 local function read(path)
  if type(readfile)~='function' then return nil end
  local ok,raw=pcall(readfile,path)
  if not ok then return nil end
  local good,data=pcall(http.JSONDecode,http,raw)
  if good and type(data)=='table' and data.Version==1 and type(data.UI)=='table' and type(data.Farm)=='table' then return data end
 end
 p.Data=read(filename) or read(filename..'.backup') or {}
 if p.Data.DefaultsRevision~=4 then p.Data={DefaultsRevision=4,UI={Theme='Standard'},Farm={}} end
 if p.Available then
  if type(makefolder)=='function' then
   local ok,err=pcall(makefolder,folder)
   if not ok and (type(isfolder)~='function' or not isfolder(folder)) then p.Available=false;p.Error=tostring(err) end
  elseif type(isfolder)~='function' or not isfolder(folder) then
   p.Available=false;p.Error='Folder creation unavailable'
  end
 end
 function p.Save(data)
  if not p.Available then return false end
  local ok,raw=pcall(http.JSONEncode,http,data)
  if not ok then p.Error=tostring(raw);return false end
  local good,err=pcall(writefile,filename,raw)
  if not good then p.Error=tostring(err);return false end
  -- A second complete snapshot allows recovery from a partially written file.
  pcall(writefile,filename..'.backup',raw)
  p.Data=data;p.Error=nil
  return true
 end
 return p
end)()

