local viewport=Vector2.zero
-- Preserve the same horizontal, two-column composition on every display.
-- The desktop size is capped; smaller viewports proportionally scale to fit.
local function fit()
 local camera=workspace.CurrentCamera
 if not camera then return end
 viewport=camera.ViewportSize
 local topInset,bottomInset=game:GetService('GuiService'):GetGuiInset()
 local safe=viewport-topInset-bottomInset
 local preferredWidth=math.min(1100,safe.X*.75)
 local baseScale=math.min(preferredWidth/1200,safe.Y*.78/620)
 local fitScale=math.min(math.max(1,safe.X-28)/1200,math.max(1,safe.Y-28)/620)
 uiScale.Scale=math.min(baseScale*state.scale/100,fitScale)
 for _,p in pairs(pages) do p.ClipsDescendants=p.Name=='Farm' or p.Name=='Utilities' or p.Name=='Settings' end
 if dropdown.open then dropdown.set(false,true) end
end
local function refreshNav()
