 for i,s in ipairs(swatchButtons) do s.ring.Transparency=i==state.accent and 0 or 1 end
 themeText.Text=state.theme=='Space' and 'Deep Void' or state.theme
 spaceArt.group.Visible=state.theme=='Space'
