   pieces[#pieces+1]=string.char(math.floor(n/65536)%256)
   if c~=61 and c then pieces[#pieces+1]=string.char(math.floor(n/256)%256) end
   if d~=61 and d then pieces[#pieces+1]=string.char(n%256) end
  end
  bannerBinary=table.concat(pieces);return bannerBinary
 end
 local function requestFor(url,message)
  local boundary='Fyrelith'..H:GenerateGUID(false):gsub('-','')
  local body='--'..boundary..'\r\nContent-Disposition: form-data; name="payload_json"\r\nContent-Type: application/json\r\n\r\n'..H:JSONEncode(payload(message))..'\r\n'
   ..'--'..boundary..'\r\nContent-Disposition: form-data; name="files[0]"; filename="violet-eclipse.jpg"\r\nContent-Type: image/jpeg\r\n\r\n'..banner()..'\r\n--'..boundary..'--\r\n'
  return {Url=url,Method='POST',Headers={['Content-Type']='multipart/form-data; boundary='..boundary},Body=body}
 end
 A.BuildWebhookRequest=requestFor


 function A.WebhookNotify(message)
  if not A.Alive or not A.Config.WebhookEnabled or not valid(A.Config.WebhookURL) then return end
  if #queue>=20 then table.remove(queue,1) end
  queue[#queue+1]={URL=A.Config.WebhookURL,Message=tostring(message):sub(1,1200)}
 end
 local lastTest=-100
 function A.TestWebhook(callback)
  local function finish(ok,message)
   A.WebhookStatus=message
   if A.Alive and type(callback)=='function' then pcall(callback,ok,message) end
  end
  local url=A.Config.WebhookURL
  if not A.Alive then return end
  if not valid(url) then finish(false,'Enter a valid HTTPS webhook URL.');return end
  if type(send)~='function' then finish(false,'Executor HTTP requests unavailable.');return end
  if busy or os.clock()-lastTest<5 then finish(false,'Please wait before testing again.');return end
  busy=true;lastTest=os.clock();A.WebhookStatus='Sending test...'
  task.spawn(function()
   local ok,result=pcall(function()return send(requestFor(url,'Webhook test'))end)
   busy=false
   local code=ok and type(result)=='table' and tonumber(result.StatusCode or result.Status)
   if code and code>=200 and code<300 then finish(true,'Test sent successfully.')
   elseif code==429 then finish(false,'Rate limited. Please try again later.')
   elseif code then finish(false,'Test failed (HTTP '..code..').')
   else finish(false,'Test failed. Check URL and executor HTTP support.') end
  end)
 end
 local previous=A.Stop
 A.Stop=function()table.clear(queue);previous()end
 table.insert(A.Connections,RS.Heartbeat:Connect(function(dt)
  elapsed+=dt;if elapsed<1 then return end;elapsed=0
  if not A.Alive then return end
  local now=os.clock();local url=A.Config.WebhookURL
  if not A.Config.WebhookEnabled or not valid(url) then
   table.clear(queue);previousBoss=nil;activeURL=nil;nextAutoAt=nil;A.WebhookNextSendAt=nil;return
  end
  -- Every automatic notification shares one five-minute window.
  if activeURL~=url then
   activeURL=url;nextAutoAt=now+300;A.WebhookNextSendAt=nextAutoAt
   table.clear(queue);previousBoss=A.PriorityBoss;return
  end
  if previousBoss and previousBoss.Parent and (tonumber(previousBoss:GetAttribute('HP')) or 1)<=0 then
   A.WebhookNotify('Boss defeated nearby: '..previousBoss.Name);previousBoss=nil
  end
  previousBoss=A.PriorityBoss
  if busy or not nextAutoAt or now<nextAutoAt then return end
  local lines={'Farm summary - last 5 minutes'}
  if #queue>0 then
   lines[#lines+1]='Recent events:'
   for i=math.max(1,#queue-4),#queue do
    local entry=queue[i]
    if entry.URL==url then lines[#lines+1]='- '..entry.Message:sub(1,180) end
   end
  end
  table.clear(queue)
  nextAutoAt=now+300;A.WebhookNextSendAt=nextAutoAt
  if type(send)~='function' then A.WebhookStatus='Executor HTTP requests unavailable';return end
  local message=table.concat(lines,'\n')
  busy=true
  task.spawn(function()
   if not A.Alive or not A.Config.WebhookEnabled or url~=A.Config.WebhookURL then busy=false;return end
   local ok,result=pcall(function()return send(requestFor(url,message))end)
   local code=ok and type(result)=='table' and tonumber(result.StatusCode or result.Status)
   A.WebhookStatus=code and code>=200 and code<300 and 'Notification sent' or 'Notification failed'
   busy=false
  end)
 end))
end

local function installExtraVisuals(A,ownerGui)
 local RS=game:GetService('RunService');local P=game:GetService('Players').LocalPlayer
 local CS=game:GetService('CollectionService')
 -- One idle event handler; no polling or held inputs.
 table.insert(A.Connections,P.Idled:Connect(function()
  if not A.Alive or not A.Config.AntiAFK then return end
