 end))

 local staminaOn=false;local staminaConfig;local staminaOriginal={}
 local ok,config=pcall(function()return require(game.ReplicatedStorage.Shared.StaminaConfig)end)
 if ok then staminaConfig=config end
 local function stamina(value)
  if not staminaConfig then return end
