 local fxNames={LumiBossSkillFx=true,SkillFxPlus=true,LumiBossFx=true,LumiStatusFx=true,LumiShapeFx=true,LumiSpawnFx=true,LumiRagFx=true,LumiFx=true,LumiSwirlFx=true,LumiCutsceneSkill=true,LumiMagicCircle=true,LumiBuffOrbs=true,LumiTargetRing=true,LumiBotAttackRange=true,LumiBotRange=true}
 local originals=setmetatable({},{__mode='k'});local tracks=setmetatable({},{__mode='k'})
 local forced=setmetatable({},{__mode='k'});local guards=setmetatable({},{__mode='k'})
 local invisible=NumberSequence.new(1)
 local disabled={};local queue={};local fxOn=false;local freezeOn=false;local stopped=false;local elapsed=0;local lastTrackScan=-100
 local frozenScript;local scriptWasEnabled
 local function matches(current,value)
  if typeof(value)=='NumberSequence' then
   if typeof(current)~='NumberSequence' then return false end
   for _,point in ipairs(current.Keypoints) do if point.Value~=1 then return false end end
   return true
  end
  return current==value
 end
 local function set(obj,key,value)
  local saved=originals[obj];if not saved then saved={};originals[obj]=saved end
  if saved[key]==nil then local ok,v=pcall(function()return obj[key]end);if not ok then return end;saved[key]=v end
  local targets=forced[obj];if not targets then targets={};forced[obj]=targets end;targets[key]=value
  local watched=guards[obj];if not watched then watched={};guards[obj]=watched end
  if not watched[key] then
   local ok,connection=pcall(function()return obj:GetPropertyChangedSignal(key):Connect(function()
    if stopped or not A.Alive or not A.Config.DisableSkillFX then return end
    local target=forced[obj] and forced[obj][key]
    if target~=nil then pcall(function()if not matches(obj[key],target) then obj[key]=target end end) end
   end)end)
   if ok then watched[key]=connection end
  end
  pcall(function()if not matches(obj[key],value) then obj[key]=value end end)
 end
 local function isFx(obj)
  local x=obj
  while x and x~=workspace do
   if fxNames[x.Name] or x.Name:match('SkillFx') or x.Name:match('SkillFX') or x.Name:match('Aura$') or x.Name:match('HealFx') then return true end
   x=x.Parent
  end
  return false
 end
 local function hide(obj)
  local emitter=obj:IsA('ParticleEmitter') or obj:IsA('Beam') or obj:IsA('Trail') or obj:IsA('Fire') or obj:IsA('Smoke') or obj:IsA('Sparkles') or obj:IsA('Light') or obj:IsA('Explosion')
  if not emitter and not isFx(obj) then return end
  if obj:IsA('BasePart') then set(obj,'LocalTransparencyModifier',1);set(obj,'Transparency',1);set(obj,'CastShadow',false)
  elseif obj:IsA('ParticleEmitter') then
   set(obj,'Transparency',invisible);set(obj,'Enabled',false);set(obj,'Rate',0);obj:Clear()
  elseif obj:IsA('Trail') then set(obj,'Transparency',invisible);set(obj,'Enabled',false);obj:Clear()
  elseif obj:IsA('Beam') then set(obj,'Transparency',invisible);set(obj,'Enabled',false)
  elseif obj:IsA('Light') or obj:IsA('Fire') or obj:IsA('Smoke') or obj:IsA('Sparkles') then set(obj,'Enabled',false)
  elseif obj:IsA('Explosion') then set(obj,'Visible',false)
  elseif obj:IsA('BillboardGui') or obj:IsA('SurfaceGui') or obj:IsA('Highlight') then set(obj,'Enabled',false)
  elseif obj:IsA('Decal') or obj:IsA('Texture') then set(obj,'Transparency',1) end
 end
 local function restoreFx()
  for _,watched in pairs(guards) do for _,connection in pairs(watched) do connection:Disconnect() end end
  table.clear(guards);table.clear(forced)
  for obj,props in pairs(originals) do for key,v in pairs(props) do pcall(function()obj[key]=v end) end end
  table.clear(originals);table.clear(queue)
 end
 local function freeze(value)
  if freezeOn==value then return end;freezeOn=value
  if not value then
   if frozenScript then pcall(function()frozenScript.Enabled=scriptWasEnabled end);frozenScript=nil end
   for _,c in ipairs(disabled) do pcall(function()c:Enable()end) end;table.clear(disabled)
   for track,speed in pairs(tracks) do pcall(function()track:AdjustSpeed(speed)end) end;table.clear(tracks)
   return
  end
  local script=P.PlayerScripts:FindFirstChild('MonsterAnimClient')
  if script and type(getconnections)=='function' then
   for _,signal in ipairs({RS.RenderStepped,RS.Heartbeat,RS.Stepped}) do
    local ok,list=pcall(getconnections,signal)
    if ok then for _,c in ipairs(list) do
     local good,env=pcall(function()return c.Function and getfenv(c.Function)end)
     if good and env and env.script==script and c.Enabled then
      local done=pcall(function()c:Disable()end);if done then disabled[#disabled+1]=c end
     end
    end end
   end
  end
  if #disabled==0 and script then
   local ok=pcall(function()scriptWasEnabled=script.Enabled;script.Enabled=false end)
   if ok then frozenScript=script end
  end
  A.FrozenMonsterDrivers=#disabled+(frozenScript and 1 or 0)
 end
 table.insert(A.Connections,workspace.DescendantAdded:Connect(function(obj)
  if A.Config.DisableSkillFX and not stopped then hide(obj) end
 end))
 table.insert(A.Connections,RS.Heartbeat:Connect(function(dt)
  if stopped or not A.Alive then return end
  stamina(A.Config.InfiniteStamina==true)
  elapsed+=dt;if elapsed<.15 then return end;elapsed=0
  if fxOn~=A.Config.DisableSkillFX then
   fxOn=A.Config.DisableSkillFX
   if fxOn then
    for _,obj in ipairs(workspace:QueryDescendants('BasePart, ParticleEmitter, Beam, Trail, Light, Decal, Texture, Fire, Smoke, Sparkles, BillboardGui, SurfaceGui, Highlight, Explosion')) do
     if isFx(obj) or obj:IsA('ParticleEmitter') or obj:IsA('Beam') or obj:IsA('Trail') or obj:IsA('Fire') or obj:IsA('Smoke') or obj:IsA('Sparkles') or obj:IsA('Light') or obj:IsA('Explosion') then hide(obj) end
    end
   else restoreFx() end
  end
  freeze(A.Config.FreezeMobs==true)
  if freezeOn and os.clock()-lastTrackScan>.8 then
   lastTrackScan=os.clock()
   for _,m in ipairs(CS:GetTagged('Monster')) do
    local animator=m:FindFirstChildWhichIsA('Animator',true)
    if animator then for _,track in ipairs(animator:GetPlayingAnimationTracks()) do
     if tracks[track]==nil then tracks[track]=track.Speed;track:AdjustSpeed(0) end
    end end
   end
  end
 end))
 local renderName='FyrelithHideSkillFX'
 RS:BindToRenderStep(renderName,Enum.RenderPriority.Last.Value+10,function()
  if not fxOn or stopped then return end
