local function installPerformance(A,ownerGui)
 local RS=game:GetService('RunService');local Lighting=game:GetService('Lighting')
 local remembered=setmetatable({},{__mode='k'});local pending={};local enabled=false;local stopped=false
 local function change(obj,key,value)
  local values=remembered[obj]
  if not values then values={};remembered[obj]=values end
  if values[key]==nil then local ok,v=pcall(function()return obj[key]end);if not ok then return end;values[key]={Value=v} end
  pcall(function()obj[key]=value end)
 end
 local function apply(obj)
  if obj.Name=='FyrelithESP' or obj:FindFirstAncestor('FyrelithESP') then return end
  if obj:IsA('BasePart') then
   change(obj,'Material',Enum.Material.Plastic);change(obj,'MaterialVariant','');change(obj,'Reflectance',0);change(obj,'CastShadow',false)
   -- Keep collision, targeting and loot instances intact; strip cosmetic rendering.
   if (obj.Anchored and not obj.CanCollide) or obj:FindFirstAncestorWhichIsA('Accessory') then change(obj,'LocalTransparencyModifier',1) end
   if obj:IsA('MeshPart') then change(obj,'TextureID','');change(obj,'RenderFidelity',Enum.RenderFidelity.Performance) end
  elseif obj:IsA('SurfaceAppearance') then
   for _,key in ipairs({'ColorMap','MetalnessMap','NormalMap','RoughnessMap'}) do change(obj,key,'') end
  elseif obj:IsA('Shirt') then change(obj,'ShirtTemplate','')
  elseif obj:IsA('Pants') then change(obj,'PantsTemplate','')
  elseif obj:IsA('ShirtGraphic') then change(obj,'Graphic','')
  elseif obj:IsA('BillboardGui') or obj:IsA('SurfaceGui') or obj:IsA('Highlight') then change(obj,'Enabled',false)
  elseif obj:IsA('Explosion') then change(obj,'Visible',false)
  elseif obj:IsA('Decal') or obj:IsA('Texture') then change(obj,'Transparency',1)
  elseif obj:IsA('SpecialMesh') then change(obj,'TextureId','')
  elseif obj:IsA('ParticleEmitter') or obj:IsA('Trail') or obj:IsA('Beam') or obj:IsA('Fire') or obj:IsA('Smoke') or obj:IsA('Sparkles') or obj:IsA('Light') or obj:IsA('PostEffect') then
   change(obj,'Enabled',false)
   if obj:IsA('ParticleEmitter') then change(obj,'Rate',0);change(obj,'Lifetime',NumberRange.new(0));obj:Clear()
   elseif obj:IsA('Trail') then change(obj,'Lifetime',0);obj:Clear() end
  elseif obj:IsA('Atmosphere') then change(obj,'Density',0);change(obj,'Haze',0);change(obj,'Glare',0)
  elseif obj:IsA('Clouds') then change(obj,'Cover',0);change(obj,'Density',0)
  elseif obj:IsA('Sky') then change(obj,'StarCount',0);change(obj,'SunAngularSize',0);change(obj,'MoonAngularSize',0)
   change(obj,'CelestialBodiesShown',false)
   for _,key in ipairs({'SkyboxBk','SkyboxDn','SkyboxFt','SkyboxLf','SkyboxRt','SkyboxUp','SunTextureId','MoonTextureId'}) do change(obj,key,'') end
  end
 end
 local selector='BasePart, Decal, Texture, SpecialMesh, ParticleEmitter, Trail, Beam, Fire, Smoke, Sparkles, Light, PostEffect, Atmosphere, Clouds, Sky, SurfaceAppearance, Shirt, Pants, ShirtGraphic, BillboardGui, SurfaceGui, Highlight, Explosion'
 local function restore()
  table.clear(pending)
  for obj,values in pairs(remembered) do
   for key,entry in pairs(values) do pcall(function()obj[key]=entry.Value end) end
  end
  table.clear(remembered)
 end
 local function boost(value)
  if enabled==value then return end;enabled=value
  if not value then restore();return end
  change(Lighting,'GlobalShadows',false);change(Lighting,'EnvironmentDiffuseScale',0);change(Lighting,'EnvironmentSpecularScale',0)
  change(Lighting,'ShadowSoftness',0);change(Lighting,'FogEnd',1000000)
  local terrain=workspace.Terrain
  change(terrain,'WaterWaveSize',0);change(terrain,'WaterWaveSpeed',0);change(terrain,'WaterReflectance',0);change(terrain,'Decoration',false);change(terrain,'WaterTransparency',1)
  local good,userSettings=pcall(function()return UserSettings():GetService('UserGameSettings')end)
  if good then change(userSettings,'SavedQualityLevel',Enum.SavedQualitySetting.QualityLevel1) end
  local ok,render=pcall(function()return settings().Rendering end)
  if ok then change(render,'QualityLevel',Enum.QualityLevel.Level01) end
  for _,obj in ipairs(workspace:QueryDescendants(selector)) do pending[#pending+1]=obj end
  for _,obj in ipairs(Lighting:GetChildren()) do apply(obj) end
 end
 local function added(obj)if enabled and not stopped then pending[#pending+1]=obj end end
 table.insert(A.Connections,workspace.DescendantAdded:Connect(added))
 table.insert(A.Connections,Lighting.ChildAdded:Connect(added))
 local previous3D
 table.insert(A.Connections,RS.Heartbeat:Connect(function()
  if stopped or not A.Alive then return end
  boost(A.Config.BoostFPS==true)
  if previous3D~=A.Config.Disable3D then
   local ok,err=pcall(function()RS:Set3dRenderingEnabled(not A.Config.Disable3D)end)
   previous3D=A.Config.Disable3D
   A.RenderingError=not ok and tostring(err) or nil
  end
  if enabled then
   local started=os.clock()
   for i=1,240 do
    if os.clock()-started>.002 then break end local obj=table.remove(pending);if not obj then break end;if obj.Parent then apply(obj) end end
   A.BoostPending=#pending
  end
 end))
 local function stop()
  if stopped then return end;stopped=true;restore()
  pcall(function()RS:Set3dRenderingEnabled(true)end)
 end
 local previous=A.Stop;A.Stop=function()stop();previous()end
 ownerGui.Destroying:Connect(stop)
end

local function installESP(A,ownerGui)
 local Players=game:GetService('Players');local P=Players.LocalPlayer
 local CS=game:GetService('CollectionService');local RS=game:GetService('RunService')
 local old=workspace:FindFirstChild('FyrelithESP');if old then old:Destroy() end
 local folder=Instance.new('Folder');folder.Name='FyrelithESP';folder.Parent=workspace
 local colors={Player=Color3.fromRGB(94,197,255),Item=Color3.fromRGB(255,207,93),Mobs=Color3.fromRGB(108,230,145),Boss=Color3.fromRGB(255,105,112),NPC=Color3.fromRGB(197,152,255)}
 local entries={};local dead=false;local elapsed=0
 local function clear()
  if dead then return end;dead=true
  folder:Destroy();table.clear(entries)
 end
 local previous=A.Stop
 A.Stop=function()clear();previous()end
 local destroying=ownerGui.Destroying:Connect(clear)
 table.insert(A.Connections,RS.Heartbeat:Connect(function(dt)
  elapsed+=dt;if elapsed<.65 then return end;elapsed=0
  if dead or not A.Alive then return end
  if not (A.Config.ESPPlayer or A.Config.ESPItem or A.Config.ESPMobs or A.Config.ESPBoss or A.Config.ESPNPC) and next(entries)==nil then return end
  local char=P.Character;local root=char and char:FindFirstChild('HumanoidRootPart')
  local camera=workspace.CurrentCamera;local origin=root and root.Position or camera and camera.CFrame.Position
  local found={};local unique={}
  local function add(target,kind,name)
   if not origin or not target or not target.Parent or unique[target] or target:GetAttribute('LumiHiddenLocal')==true then return end
   local part=target:IsA('BasePart') and target or target:IsA('Model') and (target.PrimaryPart or target:FindFirstChildWhichIsA('BasePart',true))
   if not part then return end
   local distance=(part.Position-origin).Magnitude
   if distance>1500 then return end
   unique[target]=true;found[#found+1]={Object=target,Part=part,Kind=kind,Name=name or target:GetAttribute('DisplayNameEn') or target:GetAttribute('DisplayName') or target.Name,Distance=distance}
  end
  if A.Config.ESPPlayer then for _,pl in ipairs(Players:GetPlayers()) do if pl~=P and pl.Character then add(pl.Character,'Player',pl.DisplayName) end end end
  if A.Config.ESPItem then
   for _,tag in ipairs({'Drop','LootBox'}) do for _,v in ipairs(CS:GetTagged(tag)) do add(v,'Item') end end
  end
  if A.Config.ESPMobs or A.Config.ESPBoss then
   for _,m in ipairs(CS:GetTagged('Monster')) do
    local boss=m:GetAttribute('IsBoss')==true or m:GetAttribute('IsMiniBoss')==true
    if (tonumber(m:GetAttribute('HP')) or 1)>0 and ((boss and A.Config.ESPBoss) or (not boss and A.Config.ESPMobs)) then add(m,boss and 'Boss' or 'Mobs') end
   end
  end
  if A.Config.ESPNPC then
   for _,tag in ipairs({'LumiNpc','EventNpc'}) do for _,m in ipairs(CS:GetTagged(tag)) do add(m,'NPC') end end
   local map=workspace:FindFirstChild('Map');local npcs=map and map:FindFirstChild('NPCs')
   if npcs then for _,m in ipairs(npcs:GetChildren()) do add(m,'NPC') end end
  end
  table.sort(found,function(a,b)return a.Distance<b.Distance end)
  local keep={}
  for i,target in ipairs(found) do
   if i>180 then break end
   local obj=target.Object;keep[obj]=true
   local entry=entries[obj]
   if not entry then
    local label=Instance.new('BillboardGui');label.Name='ESPLabel';label.AlwaysOnTop=true;label.Size=UDim2.fromOffset(220,44);label.StudsOffsetWorldSpace=Vector3.new(0,3,0);label.MaxDistance=1500;label.Parent=folder
    local text=Instance.new('TextLabel');text.BackgroundTransparency=1;text.Size=UDim2.fromScale(1,1);text.Font=Enum.Font.GothamBold;text.TextSize=15;text.TextStrokeColor3=Color3.fromRGB(5,8,14);text.TextStrokeTransparency=.15;text.Parent=label
    entry={Gui=label,Text=text};entries[obj]=entry
   end
   entry.Gui.Enabled=true
   local color=colors[target.Kind]
   if entry.Gui.Adornee~=target.Part then entry.Gui.Adornee=target.Part end
   if entry.Text.TextColor3~=color then entry.Text.TextColor3=color end
   local caption=target.Name..'  ·  '..math.floor(target.Distance)..' studs'
   if entry.Text.Text~=caption then entry.Text.Text=caption end
   if i<=28 then
    if not entry.Highlight then
     local h=Instance.new('Highlight');h.Name='ESPOutline';h.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop;h.FillTransparency=.85;h.OutlineTransparency=.05;h.Parent=folder;entry.Highlight=h
    end
    entry.Highlight.Enabled=true;entry.Highlight.Adornee=obj;entry.Highlight.FillColor=color;entry.Highlight.OutlineColor=color
   elseif entry.Highlight then entry.Highlight:Destroy();entry.Highlight=nil end
  end
  A.ESPCount=math.min(#found,180)
  for obj,entry in pairs(entries) do if not keep[obj] then entry.Gui:Destroy();if entry.Highlight then entry.Highlight:Destroy() end;entries[obj]=nil end end
 end))
end

local function installEconomy(A)
