 local function inShape(z,pos,margin)
  if z.Kind=='circle' or z.Safe then
   if typeof(z.Center)~='Vector3' or type(z.Radius)~='number' then return false end
   return math.abs(pos.Y-z.Center.Y)<18 and Vector3.new(pos.X-z.Center.X,0,pos.Z-z.Center.Z).Magnitude<=math.max(0,z.Radius+margin)
  elseif z.Kind=='cone' and typeof(z.Center)=='Vector3' and typeof(z.Dir)=='Vector3' then
   local v=Vector3.new(pos.X-z.Center.X,0,pos.Z-z.Center.Z)
