   elseif flat.Magnitude>reach+2 and flat.Magnitude<180 then
    local pos=m.PrimaryPart.Position+flat.Unit*math.max(3,reach)
    action={Kind='attack',Position=floorPoint(pos,root,monsters) or Vector3.new(pos.X,root.Position.Y,pos.Z)}
   else action=nil;A.Status='Fighting' end
  else action=nil;A.Status='Finding monsters' end
 end
 local function tick(dt)
  if not A.Alive then return end
  local now=os.clock()
  if nativeSetting and now-nativeRequestedAt>2 then nativeSetting=false end
  if A.Config.Equip and A.EquipDirty and now-lastEquip>1.5 then
   A.EquipDirty=false;lastEquip=now
   if R:FindFirstChild('EquipItem') then R.EquipItem:FireServer('@best') end
  end
  if A.Config.EquipCards and now-lastCardCheck>2 and not A.Selling and not A.EventClaiming then
   lastCardCheck=now
   local parts={P:GetAttribute('EquipJson') or '',P:GetAttribute('WeaponId') or '',tostring(P:GetAttribute('Level') or 1),P:GetAttribute('CardsJson') or ''}
   local cards={}
   for id,count in pairs(decode(P:GetAttribute('ItemsJson'))) do
    local def=cardDefinitions[id]
    if type(def)=='table' and def.Kind=='card' and type(count)=='number' then cards[#cards+1]=id..':'..count end
   end
   table.sort(cards);parts[#parts+1]=table.concat(cards,',')
   local signature=table.concat(parts,'|')
   if signature~=A.CardSignature or now-(A.LastCardAttempt or -100)>20 then
    A.CardSignature=signature
    A.CardEquipQueued=true
   end
  end
  local _,hum,root=character()
  if hum and hum.Health<=0 then respawnFree() end
  if (A.Selling or A.EventClaiming or A.CardEquipping) and root then
   action=nil;moving=false;targetOff();hum:Move(Vector3.zero,false)
   A.Status=A.CardEquipping and 'Equipping best cards' or A.EventClaiming and 'Claiming Ron event rewards' or 'Selling selected items';return
  end
  if A.ManualTeleport and root then
   local trip=A.ManualTeleport;action=nil;targetOff();hum:Move(Vector3.zero,false)
   if not trip.At then
    root.CFrame=CFrame.new(trip.Position or zoneCenter(trip.Zone))*root.CFrame.Rotation
    root.AssemblyLinearVelocity=Vector3.zero
    if trip.Zone then requestZone(trip.Zone) end;trip.At=now
   end
   if now-trip.At>.6 then A.ManualTeleport=nil end
   return
  end
  if A.Config.Enabled and root then
   ensureNative()
   if P:GetAttribute('AutoOn')==true then recovering=false;A.ResumeAfterSell=false end
  end
  if not A.Config.Enabled or not root or P:GetAttribute('AutoOn')~=true then
   action=nil;moving=false
   A.Status=not root and 'Waiting for character' or 'Paused'
   return
  end
  if now>=nextPlan then nextPlan=now+(next(A.Hazards) and .075 or .18);plan(root,now) end
  moving=action~=nil
  if not action then return end
  if action.Kind=='hold' then hum:Move(Vector3.zero,false);targetOff();return end
  if action.Kind=='fly' then
   local m=action.Monster;local part=m and m.Parent and m.PrimaryPart
   if not part or (tonumber(m:GetAttribute('HP')) or 0)<=0 then action=nil;return end
   local reach=range.Attack(P)+(tonumber(m:GetAttribute('Radius')) or 1.5)-1.5
   local radius=math.clamp(reach*.7,2,12)
   local offset=root.Position-part.Position
   local phase=math.atan2(offset.Z,offset.X)
   if Vector3.new(offset.X,0,offset.Z).Magnitude<radius+4 then
    phase+=math.clamp(farmMoveSpeed()/radius,2,14.4)*math.min(dt,.05)
   end
   local destination=part.Position+Vector3.new(math.cos(phase)*radius,math.min(2,reach*.3),math.sin(phase)*radius)
   local delta=destination-root.Position;local step=farmMoveSpeed()*math.min(dt,.05)
   local pos=delta.Magnitude>step and root.Position+delta.Unit*step or destination
   if A.Config.Dodge and danger(pos) then hum:Move(Vector3.zero,false);return end
   hum:Move(Vector3.zero,false)
   root.CFrame=CFrame.lookAt(pos,Vector3.new(part.Position.X,pos.Y,part.Position.Z))
   root.AssemblyLinearVelocity=Vector3.zero;root.AssemblyAngularVelocity=Vector3.zero
   A.Status='Flying around monster';return
  end
  local pos=action.Position
  if not pos then return end
  local delta=pos-root.Position
  local dodge=action.Kind=='dodge'
  if dodge or action.Kind=='box' or action.Kind=='item' or action.Kind=='zone' then targetOff() end
  local step=(dodge and 180 or farmMoveSpeed())*math.min(dt,.05)
  if delta.Magnitude>3 then
   local teleport=A.Config.Movement=='TP' and not dodge
   local nextPos=teleport and pos or root.Position+(delta.Magnitude>step and delta.Unit*step or delta)
   if not dodge and A.Config.Dodge and danger(nextPos) then
    hum:Move(Vector3.zero,false);A.Status='Waiting for skill area to clear';return
   end
   hum:Move(Vector3.zero,false)
   if teleport then
    if now-(A.LastTeleport or -100)<.35 then return end
    A.LastTeleport=now
   end
   root.CFrame=CFrame.new(nextPos)*root.CFrame.Rotation
   root.AssemblyLinearVelocity=Vector3.zero
   A.Status=({box='Moving to box',item='Collecting items',zone='Moving to next zone',attack='Moving to monster',dodge='Dodging skill'})[action.Kind]
  else
   hum:Move(Vector3.zero,false)
   if action.Kind=='box' or action.Kind=='item' then
    local obj=action.Object
    if removed(obj) then
     local key=action.Kind=='box' and 'Boxes' or 'Items';A.Stats[key]+=1;action=nil;return
    end
    if now>=action.Next then
     if action.Tries>=3 then cooldown[obj]=now+4;action=nil;return end
     action.Tries+=1;action.Next=now+.45
     if action.Kind=='box' then
      local prompt=obj:FindFirstChildOfClass('ProximityPrompt')
      if prompt and type(fireproximityprompt)=='function' then fireproximityprompt(prompt)
      else R.OpenLootBox:FireServer(obj) end
      A.Status='Opening box'
     else R.PickupDrop:FireServer();A.Status='Picking up items' end
    end
   elseif action.Kind=='zone' then action=nil
   elseif dodge then A.Status='Safe from marked area'
   else action=nil end
  end
 end
 local retryAt=0
 connect(RS.RenderStepped,function(dt)
  if os.clock()<retryAt then return end
  local ok,err=pcall(tick,dt)
  if not ok then A.Status='Retrying';A.LastError=tostring(err);action=nil;retryAt=os.clock()+1 end
 end)
 local desired=A.Config.Enabled
 installEconomy(A)
 A.SyncSettings()
 if hasSavedMaster and desired then
  task.spawn(function()
   local e=P:FindFirstChild('LumiMenuToggle') or P:WaitForChild('LumiMenuToggle',30)
   if A.Alive and A.Config.Enabled==desired and e then A.Set('Enabled',desired) end
  end)
 end
 return A
end

